/* =====================================================================
   WAVE 177 — UNIFIED CONTROL SYSTEM (csfloat-grade)
   Collapses 19 ad-hoc button treatments into ONE coherent system.
   Two heights (36 std / 40 CTA), one radius (8px), three surfaces
   (blue primary / one dark secondary / transparent ghost), two type
   scales (14/600 buttons, 13/500 chips). Appended last = wins among
   same-specificity rules. Layout/position/features untouched — visual
   styling of controls only.
   ===================================================================== */
:root {
  --ctl-h: 36px;            /* standard control height */
  --ctl-h-cta: 40px;        /* primary / CTA height */
  --ctl-r: var(--r-ctl);    /* the ONE button/input/chip radius (= 8px, foot of file) */
  --ctl-pad: 0 14px;        /* standard horizontal padding */
  --ctl-pad-cta: 0 16px;    /* primary horizontal padding */
  --ctl-fs: 14px;           /* button label size */
  --ctl-fw: 600;            /* button label weight */
  --ctl-fs-sm: 13px;        /* chip / meta size */
  --ctl-fw-sm: 500;         /* chip / meta weight */
  --ctl-primary: rgb(35, 123, 255);
  --ctl-primary-h: rgb(64, 142, 255);
  --ctl-primary-ink: #ffffff;
  --ctl-surface: rgb(38, 41, 48);          /* the one dark control surface (= card --bg-2) */
  --ctl-surface-h: rgb(46, 50, 58);
  --ctl-border: rgba(255, 255, 255, 0.08); /* the one control border */
  --ctl-border-h: rgba(255, 255, 255, 0.16);
  --ctl-ink: rgb(220, 226, 233);           /* secondary/ghost label */
  --ctl-ink-3: rgb(158, 167, 177);         /* low-emphasis label */
}

/* ---- 1. PRIMARY (blue, white text, 40px CTA / 36px compact) ---- */
html body .btn-accent,
html body .btn-primary,
html body button.btn-accent,
html body button.btn-primary,
html body .buy-btn,
html body button.buy-btn,
html body .item-rail-actions-buy,
html body button.item-rail-actions-buy {
  height: var(--ctl-h-cta) !important;
  min-height: var(--ctl-h-cta) !important;
  padding: var(--ctl-pad-cta) !important;
  border-radius: var(--ctl-r) !important;
  font-size: var(--ctl-fs) !important;
  font-weight: var(--ctl-fw) !important;
  background: var(--ctl-primary) !important;
  background-color: var(--ctl-primary) !important;
  border: 1px solid var(--ctl-primary) !important;
  color: var(--ctl-primary-ink) !important;
  box-shadow: none !important;
}
html body .btn-accent:hover,
html body .btn-primary:hover,
html body button.btn-accent:hover,
html body button.btn-primary:hover,
html body .buy-btn:hover,
html body .item-rail-actions-buy:hover {
  background: var(--ctl-primary-h) !important;
  background-color: var(--ctl-primary-h) !important;
  border-color: var(--ctl-primary-h) !important;
  color: var(--ctl-primary-ink) !important;
}

/* ---- 2. SECONDARY (one dark surface + one border, 36px) ---- */
html body .sort-picker-chip,
html body button.sort-picker-chip,
html body .deals-chip,
html body button.deals-chip,
html body .deals-chip.new-chip,
html body button.deals-chip.new-chip,
html body .toolbar-refresh,
html body button.toolbar-refresh,
html body .price-chip,
html body button.price-chip,
html body .sidebar .price-chip,
html body .item-rail-actions-cart,
html body button.item-rail-actions-cart,
html body .item-rail-actions-bargain,
html body button.item-rail-actions-bargain {
  height: var(--ctl-h) !important;
  min-height: var(--ctl-h) !important;
  border-radius: var(--ctl-r) !important;
  font-size: var(--ctl-fs-sm) !important;
  font-weight: var(--ctl-fw-sm) !important;
  background: var(--ctl-surface) !important;
  background-color: var(--ctl-surface) !important;
  border: 1px solid var(--ctl-border) !important;
  color: var(--ctl-ink) !important;
