/* ============================================================================
   UNIFIED SURFACE / SPACING / TYPE SYSTEM  (v261)
   One card surface, one border, one card radius (10px) + one control radius (8px),
   an 8px spacing scale, and a committed type scale. Source-of-truth layer placed
   last so it wins equal-specificity ties; targeted overrides collapse the
   accumulated one-off grays / radii / paddings / font-sizes from 200+ edit waves.
   ========================================================================== */

:root {
  /* --- SURFACES --- the one dark card/panel surface (de-facto dominant) --- */
  --surface:        rgb(27, 29, 36);          /* card / panel / modal / sidebar bg */
  --surface-2:      rgb(31, 33, 40);          /* inset / nested surface (sparingly) */
  --surface-line:   rgba(255, 255, 255, 0.07);/* the one subtle card/panel border */
  /* --- RADIUS --- one for cards/panels, one for inner controls/inputs ---
     --r-ctl now lives on the single ladder at the foot of this file; --r-card
     and --r-md are the same 10px rung, so both point at it. */
  --r-card:         var(--r-md);               /* cards, panels, modals, sidebars */
  /* --- SPACING --- re-pointed at the one --s-* ladder, value-for-value --- */
  --sp-1: var(--s-4);  --sp-2: var(--s-8);  --sp-3: var(--s-12); --sp-4: var(--s-16);
  --sp-5: var(--s-20); --sp-6: var(--s-24); --sp-7: var(--s-32); --sp-8: var(--s-48);
  --card-pad: var(--s-16);                     /* default card internal padding */
  /* --- TYPE --- re-pointed at the one --t-* ladder, value-for-value --- */
  --fs-1: var(--t-12); --fs-2: var(--t-13); --fs-3: var(--t-14); --fs-4: var(--t-16);
  --fs-5: var(--t-20); --fs-6: var(--t-24); --fs-7: var(--t-32); --fs-8: var(--t-42);
}

/* ---------------------------------------------------------------------------
   1) SURFACES — collapse every card/panel to one bg + one border + 10px radius
   --------------------------------------------------------------------------- */
html body .grid-card,
html body .listing-grid .grid-card,
html body .card,
html body .similar-card,
html body .recently-viewed-card,
html body .modal-stat-box,
html body .csfloat-home-tile,
